INSERT INTO "characterizations" VALUES(873,1145,'UV-vis','SPR band centered at about 438 nm','After reaction at 28°C, the Ag-NPs obtained showed a characteristic SPR band for Ag-NPs centered at about 445 nm and 438 nm for AG28 and AGG28, respectively','Results and discussion',8207,8363,NULL,NULL);
