INSERT INTO "characterizations" VALUES(875,1147,'XRD','peaks at 2θ 37.9, 44.1, 64.3 and 76.9 assigned to (111), (200), (220), (311) planes of fcc metallic silver (JCPDS 00-004-0783)','The XRD peaks at 2θ degrees of 37.9, 44.1, 64.3, and 76.9 and can be attributed to the (111), (200), (220), and (311) crystalline planes of the face centered cubic (fcc) crystalline structure of metallic silver, respectively (JCPDS file No. 00-004-0783).','Results and discussion',10560,10814,NULL,NULL);
