INSERT INTO "characterizations" VALUES(877,1163,'XRD','pure HAp, no peaks of other calcium phosphate phases (beta-TCP, alpha-TCP, CaO)','Based on Fig 17, there are no obvious peaks for the presence of other phases of calcium phosphate like β-TCP, α-TCP, and CaO; this indicates the purity of the prepared sample.','Optimization of HAp powder characteristics',38021,38196,NULL,NULL);
