INSERT INTO "characterizations" VALUES(879,1163,'FTIR','all the peaks of HAp, no other peaks','FTIR spectrum analysis (Fig 19) showed that the HAp obtained in optimal conditions has all the peaks of HAp.','Optimization of HAp powder characteristics',38659,38767,NULL,NULL);
INSERT INTO "characterizations" VALUES(880,1163,'EDX','Ca, P and O only, Ca/P ratio of 1.676','The Ca/P ratio of final HAp is 1.676, which confirms the purity of produced HAp [].','Optimization of HAp powder characteristics',39294,39377,NULL,NULL);
INSERT INTO "characterizations" VALUES(881,1164,'XRD (MnO2NFs)','tetragonal α-MnO2, no visible impurity peak','Moreover, no visible peak relating to impurities appears, indicating high-purity of α-MnO2.','3.1. Physical Chararazation',12533,12624,NULL,NULL);
INSERT INTO "characterizations" VALUES(882,1164,'SEM (MnO2NFs)','flower-like nanostructures composed of interconnected nanoflakes, porous','Obviously, flower-like nanostructures composed of interconnected nanoflakes suggests MnO2 nanoflowers were successfully synthesized.','3.1. Physical Chararazation',12674,12806,NULL,NULL);
