INSERT INTO "characterizations" VALUES(884,1165,'XRD','hexagonal ZnO (JCPDS-36-1451), no impurity peaks','The peaks observed in pure as well as in rare earth metal-doped ZnO nanoparticles are in accordance with the standard sample of the hexagonal ZnO as reported earlier (JCPDS-36-1451).','Structural and morphological analysis',12298,12480,NULL,NULL);
INSERT INTO "characterizations" VALUES(885,1170,'XRD','cubic ZnS phase (JCPDS 80-0020) on top of monoclinic CuO (JCPDS 45-0937) and CNT peaks, no additional peaks','which attributed to the (111), (220), and (311) crystal planes of cubic ZnS phase (JCPDS no. 80–0020)','Characterization',20852,20953,NULL,NULL);
