INSERT INTO "characterizations" VALUES(925,1262,'Raman','ID/IG de 0,90, structure graphitique plus désordonnée que celle de CuS/C-120','The measured values of ID/IG were 0.90, 0.86, and 0.88 for CuS/C-80, CuS/C-120, and CuS/C-160, respectively.','3.1. Morphological and Structural Characterization',16432,16540,NULL,NULL);
