INSERT INTO "outcomes" VALUES(3934,989,'Ru@MSNs_zeta_potential',21.2,NULL,'mV','Ru@MSNs possessed positive charge (37.3, 18.8, and 21.2 mV)','Size-controlled synthesis and characterization of Ru@MSNs nanosystems',19867,19926,NULL);
INSERT INTO "outcomes" VALUES(3935,989,'pore_size',2.69,NULL,'nm','The pore size of 20, 40, and 80 nm MSNs were about 2.88, 2.87, and 2.69 nm, respectively','Size-controlled synthesis and characterization of Ru@MSNs nanosystems',21162,21250,NULL);
INSERT INTO "outcomes" VALUES(3936,989,'drug_loading_efficiency',17.6,NULL,'%','the drug loading efficiency of 20, 40, and 80 nm Ru@MSNs was about 23.7, 21.1, and 17.6%','Size-controlled synthesis and characterization of Ru@MSNs nanosystems',22144,22232,NULL);
INSERT INTO "outcomes" VALUES(3937,989,'IC50_HepG2',0.091,NULL,'μM','the IC50 of Ru@MSNs at 20, 40, and 80 nm against HepG2 cells was about 0.017, 0.018, and 0.091 μM, respectively','Size effects on anticancer activity in vitro',23868,23979,NULL);
INSERT INTO "outcomes" VALUES(3938,989,'IC50_R-HepG2',0.044,NULL,'μM','the IC50 value of Ru@MSNs at 80 nm was lowest, which was about 0.044 μM. And the IC50 value of other two particles sized Ru@MSNs at 20 and 40 nm were about 0.253 and 0.515 μM, respectively','Anti-drug resistance of Ru@MSNs through suppressing drug efflux',39759,39947,NULL);
INSERT INTO "outcomes" VALUES(3939,989,'cumulative_release_PBS_pH7.4_48h',33.9,NULL,'%','cumulative released of RuPOP in PBS at pH 7.4 after 48 h from Ru@MSNs at 20, 40, and 80 nm diameter were about 13.8, 12.5, and 33.9%, respectively','In vitro drug release from the nanoparticles',29571,29717,NULL);
INSERT INTO "outcomes" VALUES(3940,989,'cumulative_release_HepG2_lysate_48h',48.5,NULL,'%','with the cumulative release about 48.5% after 48 h','In vitro drug release from the nanoparticles',30184,30234,NULL);
INSERT INTO "outcomes" VALUES(3941,989,'retention_HepG2_20h',80.7,NULL,'%','the smaller sized Ru@MSNs at 20 (94.2%) and 40 nm (91.7%) showed higher retention efficacy in HepG2 cells than that of the lager sized Ru@MSNs at 80 nm (80.7%)','Size effects of nanoparticles on intracellular uptake',27522,27681,NULL);
INSERT INTO "outcomes" VALUES(3942,989,'retention_R-HepG2_20h',92.7,NULL,'%','remain for a higher retention efficacy in R-HepG2 cells, which was about 86.7, 71.6, and 92.7%, respectively','Anti-drug resistance of Ru@MSNs through suppressing drug efflux',40576,40684,NULL);
INSERT INTO "outcomes" VALUES(3943,989,'apoptosis_HepG2',34.4,NULL,'%','the nanosystem at 20 nm induced 58.6% HepG2 cell apoptosis, which was much higher than that of other two Ru@MSNs at 40(37.7%) and 80 nm (34.4%)','In vitro induction of cell apoptosis',31726,31869,NULL);
INSERT INTO "outcomes" VALUES(3944,989,'apoptosis_R-HepG2',46.7,NULL,'%','Ru@MSNs at 80 nm induced 46.7% cell apoptosis, but Ru@MSNs at 40 and 20 nm only induced 27.5 and 25.1% cell apoptosis','Anti-drug resistance of Ru@MSNs through suppressing drug efflux',41130,41247,NULL);
INSERT INTO "outcomes" VALUES(3945,989,'ROS_level_HepG2',177.2,NULL,'%','Ru@MSNs at 20 nm triggered the highest ROS levels in HepG2 cells was about 266.1%, and the other two particles sized Ru@MSNs at 40 and 80 nm triggered 147.1 and 177.2% of ROS overproduction in HepG-2 cells','Overproduction of ROS stimulated by Ru@MSNs',32914,33119,NULL);
INSERT INTO "outcomes" VALUES(3946,989,'ROS_level_R-HepG2',369.3,NULL,'%','the highest ROS overproduction in R-HepG2 cells was triggered by the larger sized Ru@MSNs at 80 nm, which was reached to 369.3%','Anti-drug resistance of Ru@MSNs through suppressing drug efflux',41657,41784,NULL);
