INSERT INTO "outcomes" VALUES(4763,1171,'BET_surface_area',453.0,NULL,'m2/g','The specific surface area and total pore volume were up to 453 m2/g and 0.2838 cm3/g, respectively.','3.6. N2 Adsorption Performance',20226,20325,NULL);
INSERT INTO "outcomes" VALUES(4764,1171,'total_pore_volume',0.2838,NULL,'cm3/g','The specific surface area and total pore volume were up to 453 m2/g and 0.2838 cm3/g, respectively.','3.6. N2 Adsorption Performance',20226,20325,NULL);
INSERT INTO "outcomes" VALUES(4765,1171,'micropore_surface_area',399.0,NULL,'m2/g','453 | 399 | 0.2838 | 0.1866','4. Conclusions',22519,22546,NULL);
INSERT INTO "outcomes" VALUES(4766,1171,'micropore_volume',0.1866,NULL,'cm3/g','453 | 399 | 0.2838 | 0.1866','4. Conclusions',22519,22546,NULL);
INSERT INTO "outcomes" VALUES(4767,1171,'Si_Al_ratio',1.21,NULL,NULL,'Meanwhile, the Si/Al ratio is 1.21, which agrees with the theoretical value of 1.13 in the raw material.','3.5. TG-DTA and XRF Analysis',18260,18364,NULL);
INSERT INTO "outcomes" VALUES(4768,1171,'moisture_loss_TG',22.0,NULL,'wt %','TG results showed that the synthesized zeolite X products lost all its moisture (22 wt %) at temperatures lower than 350 °C.','3.5. TG-DTA and XRF Analysis',18773,18897,NULL);
INSERT INTO "outcomes" VALUES(4769,1171,'morphology',NULL,'octahedral crystals, uniform distribution',NULL,'However, the crystallization temperature at 110 °C formed better octahedral crystal morphology along with uniform distribution of crystals (Figure 3e,f).','3.2. Effect of Crystallization',11381,11534,NULL);
INSERT INTO "outcomes" VALUES(4770,1171,'morphology_5h',NULL,'regular crystals with smooth faces',NULL,'When the crystallization time reached 5 h, the synthesized products formed regular crystals with smooth faces.','3.2. Effect of Crystallization',12108,12218,NULL);
INSERT INTO "outcomes" VALUES(4771,1171,'morphology_Na2O_SiO2_1.4',NULL,'better octahedral structure and uniform distribution',NULL,'On the other hand, the sample with Na2O/SiO2 ratio of 1.4 exhibited better octahedral structure and uniform distribution.','3.4. Effect of Alkalinity',17233,17354,NULL);
INSERT INTO "outcomes" VALUES(4772,1172,'phase',NULL,'only one strong diffraction peak, attributed to aluminum hydroxide',NULL,'the sample at a crystallization temperature of 90 °C showed only one strong diffraction peak at 2θ = 18.35°, which can be attributed to aluminum hydroxide','3.2. Effect of Crystallization',9571,9725,NULL);
INSERT INTO "outcomes" VALUES(4773,1172,'morphology',NULL,'spherical aggregates of ill-defined particles',NULL,'When the crystallization temperature was 90 °C, the reactants formed spherical aggregates of ill-defined particles.','3.2. Effect of Crystallization',11149,11264,NULL);
INSERT INTO "outcomes" VALUES(4774,1173,'phase',NULL,'typical diffraction peaks of X zeolite, zeolite X started to crystallize',NULL,'When the temperature was raised to 100 °C, typical diffraction peaks of X zeolite (JCPDS 38-0237) can be seen at 2θ = 6.10°, 9.97°, 11.76°, 15.39°, 18.46°, 20.12°, 23.24°, 26.58° and 30.86° suggesting that zeolite X started to crystallize (Figure 2a).','3.2. Effect of Crystallization',9846,10097,NULL);
INSERT INTO "outcomes" VALUES(4775,1173,'impurity',NULL,'aluminum hydroxide peak, incomplete reaction of aluminum hydroxide and silica',NULL,'However, the diffraction peak of aluminum hydroxide can also be seen at 2θ = 18.35°, which suggested an incomplete reaction of aluminum hydroxide and silica from diatomite.','3.2. Effect of Crystallization',10098,10270,NULL);
INSERT INTO "outcomes" VALUES(4776,1174,'phase',NULL,'almost pure phase of zeolite X along with some zeolite A',NULL,'When the reaction temperature was further raised to 120 °C, almost pure phase of zeolite X was observed along with some zeolite A (JCPDS 43-0142).','3.2. Effect of Crystallization',10381,10527,NULL);
INSERT INTO "outcomes" VALUES(4777,1174,'morphology',NULL,'some cubic crystals appeared, attributed to zeolite A',NULL,'When the crystallization temperature was increased up to 120 °C, some cubic crystals appeared (Figure 3g,h), which could be attributed to the formation of zeolite A.','3.2. Effect of Crystallization',11693,11858,NULL);
INSERT INTO "outcomes" VALUES(4778,1175,'calcium_ion_exchange_capacity',NULL,'gradually decreased with temperature above 110 °C',NULL,'Increasing temperature of crystallization up to 110 °C increased the CEC but by further increasing the temperature up to 130 °C, the CEC of prepared samples gradually decreased (Figure 5a).','3.2. Effect of Crystallization',12667,12856,NULL);
INSERT INTO "outcomes" VALUES(4779,1176,'phase',NULL,'no zeolite X obtained',NULL,'As shown in Figure 2b, no zeolite X was obtained at crystallization time of 3 h at 110 °C.','3.2. Effect of Crystallization',10655,10745,NULL);
INSERT INTO "outcomes" VALUES(4780,1177,'morphology',NULL,'crystals with no distinct faces, particles not uniform',NULL,'When the crystallization time was 4 h, the synthesized products formed crystals with no distinct faces, and the particles were not uniform.','3.2. Effect of Crystallization',11968,12107,NULL);
INSERT INTO "outcomes" VALUES(4781,1178,'morphology',NULL,'products do not show smooth faces',NULL,'When the crystallization time was up to 6 h, the synthesized products do not show smooth faces.','3.2. Effect of Crystallization',12219,12314,NULL);
INSERT INTO "outcomes" VALUES(4782,1179,'phase',NULL,'extremely weak diffraction peaks of zeolite X',NULL,'However, the synthetic product without aging exhibited extremely weak diffraction peaks of zeolite X (Figure 6b).','3.3. Effect of Aging',14156,14269,NULL);
INSERT INTO "outcomes" VALUES(4783,1179,'impurity',NULL,'sharp peak at 2θ = 18.35°, unreacted aluminum hydroxide',NULL,'Also, there was a sharp diffraction peak at 2θ = 18.35°, which could be attributed to the unreacted aluminum hydroxide.','3.3. Effect of Aging',14270,14389,NULL);
INSERT INTO "outcomes" VALUES(4784,1180,'phase',NULL,'zeolite X with high crystallization degree and some obvious zeolite A peaks',NULL,'However, when the aging time was up to 60 and 120 min, some obvious diffraction peaks of zeolite A appeared indicating that the aging time plays a significant role in the formation of zeolite prepared from diatomite.','3.3. Effect of Aging',14545,14761,NULL);
INSERT INTO "outcomes" VALUES(4785,1181,'phase',NULL,'zeolite X with high crystallization degree and some obvious zeolite A peaks',NULL,'However, when the aging time was up to 60 and 120 min, some obvious diffraction peaks of zeolite A appeared indicating that the aging time plays a significant role in the formation of zeolite prepared from diatomite.','3.3. Effect of Aging',14545,14761,NULL);
INSERT INTO "outcomes" VALUES(4786,1182,'phase',NULL,'maximum crystallization degree with some zeolite A impurities (shared with ratio 40)',NULL,'When the H2O/Na2O ratios were 40 and 45, the crystallization degree reached the maximum and there were also some zeolite A impurities.','3.4. Effect of Alkalinity',16161,16295,NULL);
INSERT INTO "outcomes" VALUES(4787,1182,'impurity',NULL,'relatively sharp diffraction peak of aluminum hydroxide, incomplete reaction',NULL,'However, when the H2O/Na2O ratios were 45, a relatively sharp diffraction peak of aluminum hydroxide appeared (Figure 8a), which indicated that diatomite and aluminum hydroxide did not react completely.','3.4. Effect of Alkalinity',16296,16498,NULL);
INSERT INTO "outcomes" VALUES(4788,1183,'phase',NULL,'only one sharp diffraction peak attributable to aluminum hydroxide',NULL,'When the H2O/Na2O ratio was up to 50, there was only one sharp diffraction peak attributable to aluminum hydroxide.','3.4. Effect of Alkalinity',16499,16614,NULL);
INSERT INTO "outcomes" VALUES(4789,1184,'crystallinity_morphology',NULL,'high crystallinity with smooth faces',NULL,'Figure 9 shows that all samples with Na2O/SiO2 ratios of 1.3, 1.4 and 1.5 exhibited high crystallinity with smooth faces.','3.4. Effect of Alkalinity',17111,17232,NULL);
INSERT INTO "outcomes" VALUES(4790,1185,'crystallinity_morphology',NULL,'high crystallinity with smooth faces',NULL,'Figure 9 shows that all samples with Na2O/SiO2 ratios of 1.3, 1.4 and 1.5 exhibited high crystallinity with smooth faces.','3.4. Effect of Alkalinity',17111,17232,NULL);
