INSERT INTO "outcomes" VALUES(4844,1202,'average_particle_size',0.25,NULL,'μm','ZIF-8 nanospheres prepared with a S/O ratio of 0.10 and 0.15 g mL–1 displayed a particle size equivalent to ∼0.37 ± 0.10 and ∼0.25 ± 0.10 μm, respectively (Figure 5d,e).','Effect of the Amount of HFS Surfactant',39686,39855,NULL);
INSERT INTO "outcomes" VALUES(4845,1202,'morphology',NULL,'both solid and hollow ZIF-8 nanospheres, lower yield of hollow particles',NULL,'The increased amount of surfactant and reduction in the average particle size promoted the formation of both solid and hollow ZIF-8 nanospheres, as confirmed by the TEM image (insets in Figure 5d,e).','Effect of the Amount of HFS Surfactant',39856,40055,NULL);
INSERT INTO "outcomes" VALUES(4846,1203,'morphology',NULL,'2D leaf-shaped',NULL,'As seen in Figure 3a, the sample prepared with 0.3 g of HFS in the synthesis mixture (without n-hexane) exhibited a 2D leaf-shaped morphology, which is similar to previously reported ZIF-L crystals.','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',24529,24727,NULL);
INSERT INTO "outcomes" VALUES(4847,1203,'phase',NULL,'pure ZIF-L phase',NULL,'The XRD results also confirmed the presence of a pure ZIF-L phase (Figure 3f), which ruled out the possibility of HFS as a ZIF-L → ZIF-8 phase directing agent.','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',24728,24887,NULL);
INSERT INTO "outcomes" VALUES(4848,1204,'morphology',NULL,'spherical particles with both solid and hollow structures',NULL,'Interestingly, at low concentrations of n-hexane (3–5 v/v %) in the S-O/W emulsion, spherical particles with both solid and hollow structures appeared in the pure ZIF-8 phase (Figure 3b,c and insets).','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',24888,25088,NULL);
INSERT INTO "outcomes" VALUES(4849,1204,'phase',NULL,'single-phase ZIF-8',NULL,'Expectedly, the nanospheres prepared with 3–5 v/v % of n-hexane showed the presence of single-phase ZIF-8 (Figure 3f)','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',25787,25904,NULL);
INSERT INTO "outcomes" VALUES(4850,1205,'morphology',NULL,'spherical particles with both solid and hollow structures',NULL,'Interestingly, at low concentrations of n-hexane (3–5 v/v %) in the S-O/W emulsion, spherical particles with both solid and hollow structures appeared in the pure ZIF-8 phase (Figure 3b,c and insets).','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',24888,25088,NULL);
INSERT INTO "outcomes" VALUES(4851,1205,'phase',NULL,'single-phase ZIF-8',NULL,'Expectedly, the nanospheres prepared with 3–5 v/v % of n-hexane showed the presence of single-phase ZIF-8 (Figure 3f)','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',25787,25904,NULL);
INSERT INTO "outcomes" VALUES(4852,1206,'surfactant_oil_ratio',0.05,NULL,'g mL–1','For example, the S/O ratio is 0.05 (0.3 g/6 mL = 0.05 g mL–1) when 6 mL (13 v/v %) of n-hexane was used.','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',31529,31633,NULL);
INSERT INTO "outcomes" VALUES(4853,1207,'surfactant_oil_ratio',0.0375,NULL,'g mL–1','Similarly, the S/O ratios for 8 mL (17 v/v %) and 12 mL (23 v/v %) of n-hexane are 0.0375 and 0.025 g mL–1, respectively.','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',31634,31755,NULL);
INSERT INTO "outcomes" VALUES(4854,1208,'surfactant_oil_ratio',0.025,NULL,'g mL–1','Similarly, the S/O ratios for 8 mL (17 v/v %) and 12 mL (23 v/v %) of n-hexane are 0.0375 and 0.025 g mL–1, respectively.','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',31634,31755,NULL);
INSERT INTO "outcomes" VALUES(4855,1208,'particle_size_trend',NULL,'almost linear increase in hollow particle size',NULL,'Further decreasing the S/O ratio to 0.025 g mL–1, or increasing oil volume to 12 mL (23 v/v %), led to an almost linear increase in hollow particle size.','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',32298,32451,NULL);
INSERT INTO "outcomes" VALUES(4856,1209,'morphology',NULL,'leaf-shaped morphology',NULL,'However, the SEM images in Figure S11(I) in the Supporting Information present the formation of a leaf-shaped morphology.','Order of Reagent Addition and Ligand Concentration',50084,50205,NULL);
INSERT INTO "outcomes" VALUES(4857,1210,'morphology',NULL,'solid spherical morphology, no hollow spheres',NULL,'Instead, solid spherical morphology was observed.','Order of Reagent Addition and Ligand Concentration',50366,50415,NULL);
INSERT INTO "outcomes" VALUES(4858,1211,'morphology',NULL,'very uniform spherical morphology with a small crystal size',NULL,'Expectedly, the as-synthesized sample showed a very uniform spherical morphology with a small crystal size [Figure S11(III)].','Order of Reagent Addition and Ligand Concentration',51156,51281,NULL);
INSERT INTO "outcomes" VALUES(4859,1211,'hollow_fraction',NULL,'solid ZIF-8 crystallites with an exception of a few hollow spheres',NULL,'Figure S11(IV) shows the TEM image for elaborating the formation of solid ZIF-8 crystallites, with an exception of a few hollow sphere formations.','Order of Reagent Addition and Ligand Concentration',51384,51530,NULL);
INSERT INTO "outcomes" VALUES(4860,1212,'morphology',NULL,'2D leaf-shaped',NULL,'0 v/v % n-hexane | | 2D leaf-shaped | 200 | 2.77 | 0.21','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',23169,23224,NULL);
INSERT INTO "outcomes" VALUES(4861,1212,'phase',NULL,'only pure 2D ZIF-L',NULL,'The XRD results confirmed that only pure 2D ZIF-L was formed without n-hexane (Figure 2f).','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',20945,21035,NULL);
INSERT INTO "outcomes" VALUES(4862,1212,'BET_surface_area',200.0,NULL,'m2 g–1','0 v/v % n-hexane | | 2D leaf-shaped | 200 | 2.77 | 0.21','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',23169,23224,NULL);
