INSERT INTO "outcomes" VALUES(4864,1212,'total_pore_volume',0.21,NULL,'cm3 g–1','0 v/v % n-hexane | | 2D leaf-shaped | 200 | 2.77 | 0.21','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',23169,23224,NULL);
INSERT INTO "outcomes" VALUES(4865,1213,'crystal_size',220.0,NULL,'nm','All samples showed spherical crystals with slightly increasing sizes, from ∼220 nm (1 v/v %) to ∼260 nm (3 v/v %), and then to ∼350 nm (5 v/v %), as also shown in Figure 2b–d.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18363,18538,NULL);
INSERT INTO "outcomes" VALUES(4866,1213,'morphology',NULL,'granular shape',NULL,'Interestingly, at 1 v/v % (overall) concentration of n-hexane in mixture-I, a distinct change in crystal morphology to granular shape was observed, as shown in Figure 2b.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',17968,18138,NULL);
INSERT INTO "outcomes" VALUES(4867,1213,'phase',NULL,'mixed ZIF-L/ZIF-8 phases',NULL,'However, mixed ZIF-L/ZIF-8 phases were observed for the sample prepared with 1 v/v % of n-hexane.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',21036,21133,NULL);
INSERT INTO "outcomes" VALUES(4868,1214,'crystal_size',260.0,NULL,'nm','All samples showed spherical crystals with slightly increasing sizes, from ∼220 nm (1 v/v %) to ∼260 nm (3 v/v %), and then to ∼350 nm (5 v/v %), as also shown in Figure 2b–d.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18363,18538,NULL);
INSERT INTO "outcomes" VALUES(4869,1214,'phase',NULL,'pure ZIF-8 phase for n-hexane ≥3 v/v %',NULL,'With a further increment in the n-hexane concentration, a pure ZIF-8 phase was formed in the synthesis with n-hexane concentrations ≥3 v/v % (i.e., ≥1 mL).','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',21134,21289,NULL);
INSERT INTO "outcomes" VALUES(4870,1214,'hollow_structure',NULL,'no hollow structures, solid nanocrystals',NULL,'The absence of any hollow structures in these samples indicated that lower oil contents favored the formation of solid ZIF nanocrystals.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18539,18675,NULL);
INSERT INTO "outcomes" VALUES(4871,1215,'crystal_size',350.0,NULL,'nm','All samples showed spherical crystals with slightly increasing sizes, from ∼220 nm (1 v/v %) to ∼260 nm (3 v/v %), and then to ∼350 nm (5 v/v %), as also shown in Figure 2b–d.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18363,18538,NULL);
INSERT INTO "outcomes" VALUES(4872,1215,'phase',NULL,'pure ZIF-8 phase for n-hexane ≥3 v/v %',NULL,'With a further increment in the n-hexane concentration, a pure ZIF-8 phase was formed in the synthesis with n-hexane concentrations ≥3 v/v % (i.e., ≥1 mL).','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',21134,21289,NULL);
INSERT INTO "outcomes" VALUES(4873,1215,'hollow_structure',NULL,'no hollow structures, solid nanocrystals',NULL,'The absence of any hollow structures in these samples indicated that lower oil contents favored the formation of solid ZIF nanocrystals.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18539,18675,NULL);
INSERT INTO "outcomes" VALUES(4874,1216,'average_sphere_diameter',2.5,NULL,'μm','Figure 2e showed that a minimum of 9 v/v % of n-hexane was required to form a stable ME for initiating the growth of hollow structures with an average diameter of ∼2.50 ± 0.95 μm (Table S1) and a shell thickness of ∼0.25 ± 0.05 μm.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18804,19035,NULL);
INSERT INTO "outcomes" VALUES(4875,1216,'shell_thickness',0.25,NULL,'μm','Figure 2e showed that a minimum of 9 v/v % of n-hexane was required to form a stable ME for initiating the growth of hollow structures with an average diameter of ∼2.50 ± 0.95 μm (Table S1) and a shell thickness of ∼0.25 ± 0.05 μm.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18804,19035,NULL);
INSERT INTO "outcomes" VALUES(4876,1216,'particle_size_distribution',NULL,'broad PSD (∼0.50 to ∼5.5 μm), solid nanocrystals mixed with microsized hollow particles',NULL,'a broad PSD (∼0.50 to ∼5.5 μm) was observed, and the sample contained a majority of solid nanocrystals mixed with microsized hollow spherical particles','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',19132,19283,NULL);
INSERT INTO "outcomes" VALUES(4877,1216,'emulsion_droplet_size',NULL,'∼3.40 ± 1.10 μm',NULL,'having an average droplet size of ∼3.40 ± 1.10 μm along with the droplet size distribution curve','Pre-synthesis Ultrasonication',16408,16504,NULL);
INSERT INTO "outcomes" VALUES(4878,1216,'BET_surface_area',685.0,NULL,'m2 g–1','9 v/v % n-hexane | | hollow + solid | 685 | 1.08 | 0.38','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',23225,23280,NULL);
INSERT INTO "outcomes" VALUES(4879,1216,'pore_diameter',1.08,NULL,'nm','9 v/v % n-hexane | | hollow + solid | 685 | 1.08 | 0.38','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',23225,23280,NULL);
INSERT INTO "outcomes" VALUES(4880,1216,'total_pore_volume',0.38,NULL,'cm3 g–1','9 v/v % n-hexane | | hollow + solid | 685 | 1.08 | 0.38','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',23225,23280,NULL);
INSERT INTO "outcomes" VALUES(4881,1217,'morphology',NULL,'similar combination of solid nanocrystals and microsized hollow particles',NULL,'The increase to 17 v/v % of n-hexane did not give a big difference as the sample showed a similar combination of solid nanocrystals and microsized hollow particles (Figure S2(I)).','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',19837,20016,NULL);
INSERT INTO "outcomes" VALUES(4882,1218,'particle_size_distribution',NULL,'more uniform size and narrow PSD',NULL,'When the n-hexane volume ratio was increased to 23 v/v %, the sample with a more uniform size and narrow PSD was obtained (Table S1).','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',20017,20150,NULL);
INSERT INTO "outcomes" VALUES(4883,1218,'nano_ZIF-8_formation',NULL,'formation of nano ZIF-8s not effectively avoided',NULL,'However, this increase in the oil concentration still could not effectively avoid the formation of nano ZIF-8s due to the ME instability, as discussed above [Figure S2(II)].','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',20151,20324,NULL);
INSERT INTO "outcomes" VALUES(4884,1219,'average_sphere_diameter',1.8,NULL,'μm','reducing from ∼2.50 ± 0.95 to ∼1.80 ± 0.30 μm by simply increasing the temperature from 30 to 50 °C (Table S6)','Synthesis Temperature',47522,47632,NULL);
INSERT INTO "outcomes" VALUES(4885,1219,'nano_ZIF-8_formation',NULL,'formation of nanosized solid ZIF-8s still unavoidable',NULL,'Although the quality of the hollow sphere crop was upgraded, the formation of nanosized solid ZIF-8s was still unavoidable.','Synthesis Temperature',47912,48035,NULL);
INSERT INTO "outcomes" VALUES(4886,1220,'crystallization',NULL,'no obvious crystallization',NULL,'Interestingly, no obvious crystallization was noticed in the absence of ultrasonication pre-treatment due to the absence of the ME growth template, as shown in Figure S1(I).','Pre-synthesis Ultrasonication',16102,16275,NULL);
