INSERT INTO "reagents" VALUES(1051,1035,'oleic acid (NC synthesis)',NULL,'ligand',12.1,'mmol',NULL,'technical grade 90%','Sigma-Aldrich','Mixtures of 12.1 mmol (4 mL) of OA and 6.05 mmol of amine ligands with different ratios of (R)-2-octylamine to OAm (1:0, 0.5:0.5, 0.25:0.75, 0:1)','Synthesis of FAPbBr3 NCs',24282,24427,'Formamidinium acetate (FA-acetate, 99%), oleic acid (OA, technical grade 90%), oleylamine (OAm, technical grade 70%), 1-octadecene (ODE, technical grade 90%), hexane (reagent grade ≥95%), octane (anhydrous, ≥99%), methyl acetate (MeOAc, anhydrous 99.5%), ethyl acetate (EtOAc, anhydrous 99.5%), R-methybenzylamine (98% purity), S-methybenzylamine (98% purity), hydrobromic acid (ACS reagent, 48%), and ethyl acetate (EtOAc, anhydrous, 99.8%) were purchased from Sigma-Aldrich.');
INSERT INTO "reagents" VALUES(1052,1035,'amine ligands, total ((R)-2-octylamine + oleylamine)',NULL,'ligand',6.05,'mmol',NULL,NULL,NULL,'Mixtures of 12.1 mmol (4 mL) of OA and 6.05 mmol of amine ligands with different ratios of (R)-2-octylamine to OAm (1:0, 0.5:0.5, 0.25:0.75, 0:1)','Synthesis of FAPbBr3 NCs',24282,24427,NULL);
INSERT INTO "reagents" VALUES(1053,1035,'(R)-2-octylamine',NULL,'ligand',NULL,NULL,'0.25 (part of the 0.25:0.75 (R)-2-octylamine to OAm ratio)','98%','Alfa Aesar','Mixtures of 12.1 mmol (4 mL) of OA and 6.05 mmol of amine ligands with different ratios of (R)-2-octylamine to OAm (1:0, 0.5:0.5, 0.25:0.75, 0:1)','Synthesis of FAPbBr3 NCs',24282,24427,'(R)-2-Octylamine (98% purity) was purchased from Alfa Aesar.');
INSERT INTO "reagents" VALUES(1054,1035,'oleylamine',NULL,'ligand',NULL,NULL,'0.75 (part of the 0.25:0.75 (R)-2-octylamine to OAm ratio)','technical grade 70%','Sigma-Aldrich','Mixtures of 12.1 mmol (4 mL) of OA and 6.05 mmol of amine ligands with different ratios of (R)-2-octylamine to OAm (1:0, 0.5:0.5, 0.25:0.75, 0:1)','Synthesis of FAPbBr3 NCs',24282,24427,'Formamidinium acetate (FA-acetate, 99%), oleic acid (OA, technical grade 90%), oleylamine (OAm, technical grade 70%), 1-octadecene (ODE, technical grade 90%), hexane (reagent grade ≥95%), octane (anhydrous, ≥99%), methyl acetate (MeOAc, anhydrous 99.5%), ethyl acetate (EtOAc, anhydrous 99.5%), R-methybenzylamine (98% purity), S-methybenzylamine (98% purity), hydrobromic acid (ACS reagent, 48%), and ethyl acetate (EtOAc, anhydrous, 99.8%) were purchased from Sigma-Aldrich.');
INSERT INTO "reagents" VALUES(1055,1035,'FA-oleate stock solution',NULL,'precursor',5.0,'mL',NULL,NULL,NULL,'Under N2 flow, 5 mL of the FA-oleate stock solution was swiftly injected into the PbBr2 mixture','Synthesis of FAPbBr3 NCs',24668,24763,NULL);
INSERT INTO "reagents" VALUES(1056,1035,'hexane',NULL,'solvent',5.0,'mL',NULL,'reagent grade ≥95%','Sigma-Aldrich','The precipitate was dispersed in 5 mL of hexane, then centrifuged at 7500 rpm for 5 min to remove the precipitated large particles.','Synthesis of FAPbBr3 NCs',24953,25084,'Formamidinium acetate (FA-acetate, 99%), oleic acid (OA, technical grade 90%), oleylamine (OAm, technical grade 70%), 1-octadecene (ODE, technical grade 90%), hexane (reagent grade ≥95%), octane (anhydrous, ≥99%), methyl acetate (MeOAc, anhydrous 99.5%), ethyl acetate (EtOAc, anhydrous 99.5%), R-methybenzylamine (98% purity), S-methybenzylamine (98% purity), hydrobromic acid (ACS reagent, 48%), and ethyl acetate (EtOAc, anhydrous, 99.8%) were purchased from Sigma-Aldrich.');
INSERT INTO "reagents" VALUES(1057,1035,'nitrogen','N2','gas',NULL,NULL,NULL,NULL,NULL,'The temperature was then increased to 120 °C under N2 and kept at this temperature.','Synthesis of FA-Oleate Precursor',24000,24083,NULL);
INSERT INTO "reagents" VALUES(1058,1039,'R-,S-methylbenzylamine',NULL,'precursor',78.0,'mmol',NULL,'98%','Sigma-Aldrich','In a one-necked round-bottom flask in an ice bath, 78 mmol (10 mL) of R-,S-MBA and 30 mL of ethanol were added','Synthesis of R-,S-MBA:Br',25171,25281,'Formamidinium acetate (FA-acetate, 99%), oleic acid (OA, technical grade 90%), oleylamine (OAm, technical grade 70%), 1-octadecene (ODE, technical grade 90%), hexane (reagent grade ≥95%), octane (anhydrous, ≥99%), methyl acetate (MeOAc, anhydrous 99.5%), ethyl acetate (EtOAc, anhydrous 99.5%), R-methybenzylamine (98% purity), S-methybenzylamine (98% purity), hydrobromic acid (ACS reagent, 48%), and ethyl acetate (EtOAc, anhydrous, 99.8%) were purchased from Sigma-Aldrich.');
INSERT INTO "reagents" VALUES(1059,1039,'ethanol',NULL,'solvent',30.0,'mL',NULL,NULL,NULL,'In a one-necked round-bottom flask in an ice bath, 78 mmol (10 mL) of R-,S-MBA and 30 mL of ethanol were added','Synthesis of R-,S-MBA:Br',25171,25281,NULL);
INSERT INTO "reagents" VALUES(1060,1039,'hydrobromic acid (aqueous)','HBr','acid',116.0,'mmol',NULL,'48%','Sigma-Aldrich','then 116 mmol (13.2 mL) of HBr aqueous solution was added dropwise into the flask under vigorous stirring.','Synthesis of R-,S-MBA:Br',25283,25389,'Formamidinium acetate (FA-acetate, 99%), oleic acid (OA, technical grade 90%), oleylamine (OAm, technical grade 70%), 1-octadecene (ODE, technical grade 90%), hexane (reagent grade ≥95%), octane (anhydrous, ≥99%), methyl acetate (MeOAc, anhydrous 99.5%), ethyl acetate (EtOAc, anhydrous 99.5%), R-methybenzylamine (98% purity), S-methybenzylamine (98% purity), hydrobromic acid (ACS reagent, 48%), and ethyl acetate (EtOAc, anhydrous, 99.8%) were purchased from Sigma-Aldrich.');
INSERT INTO "reagents" VALUES(1061,1039,'diethyl ether',NULL,'wash',NULL,NULL,NULL,NULL,NULL,'then washed thoroughly by repeated redissolution in ethanol and recrystallization in diethyl ether until colorless.','Synthesis of R-,S-MBA:Br',25535,25650,NULL);
INSERT INTO "reagents" VALUES(1062,1040,'FAPbBr3 NC stock solution',NULL,'substrate',5.0,'mL',NULL,NULL,NULL,'To purify the FAPbBr3 NCs, 10 mL of MeOAc was added to 5 mL of a stock solution; then it was centrifuged at 7500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26014,26141,NULL);
