INSERT INTO "reagents" VALUES(1064,1040,'hexane',NULL,'solvent',5.0,'mL',NULL,'reagent grade ≥95%','Sigma-Aldrich','The resulting precipitate was redispersed in 5 mL of hexane and centrifuged again at 7500 rpm for 5 min to discard the aggregated particles.','Purification and Ligand Treatment of FAPbBr3 NCs',26142,26282,'Formamidinium acetate (FA-acetate, 99%), oleic acid (OA, technical grade 90%), oleylamine (OAm, technical grade 70%), 1-octadecene (ODE, technical grade 90%), hexane (reagent grade ≥95%), octane (anhydrous, ≥99%), methyl acetate (MeOAc, anhydrous 99.5%), ethyl acetate (EtOAc, anhydrous 99.5%), R-methybenzylamine (98% purity), S-methybenzylamine (98% purity), hydrobromic acid (ACS reagent, 48%), and ethyl acetate (EtOAc, anhydrous, 99.8%) were purchased from Sigma-Aldrich.');
