INSERT INTO "reagents" VALUES(1082,1065,'3-aminopropyltriethoxysilane (APTES)',NULL,'precursor',8.85,'g',NULL,NULL,'Shanghai Aladdin Biochemical Reagents','8.85 g (39.98 mmoL) of APTES, 4.88 g (39.96 mmoL) of salicylaldehyde, and 100 mL of ethanol were added to a flask and reacted at 95 °C for 3 h','2.2.1. Preparation of Salicylaldimine',8251,8393,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China).');
