INSERT INTO "reagents" VALUES(1087,1065,'anhydrous magnesium sulfate','MgSO4','desiccant',0.5,'g',NULL,NULL,'Tianjin Damao Chemical Reagents','0.5 g (4.15 mmoL) anhydrous magnesium sulfate was used to remove the residual water','2.2.1. Preparation of Salicylaldimine',8663,8746,'Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China).');
INSERT INTO "reagents" VALUES(1088,1065,'cetyl trimethyl ammonium bromide (CTAB)',NULL,'template',1.5,'g',NULL,NULL,'Shanghai Aladdin Biochemical Reagents','a total of 1.5 g (4.12 mmoL) of CTAB, 105 mL of ammonia solution (wt = 25%), and 150 mL of deionized water were added to the flask to be completely dissolved at 60 °C with 1 h of stirring','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9290,9477,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China).');
