INSERT INTO "reagents" VALUES(1093,1065,'ethanol (template removal)',NULL,'solvent',100.0,'mL',NULL,NULL,'Tianjin Damao Chemical Reagents','the template was removed with 100 mL ethanol at 110 °C for 72 h by the mean of reflux extraction to obtain Sal-MCM-41','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9751,9868,'Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China).');
