INSERT INTO "reagents" VALUES(1095,1065,'zinc nitrate solution','Zn(NO3)2','precursor',50.0,'mL',NULL,NULL,'Tianjin Damao Chemical Reagents','50 mL (100 mmoL) of zinc nitrate solution was added to 500 mg of Sal-MCM-41 or MCM-41 at 30 °C with stirring for 24 h','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10366,10483,'Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China).');
