INSERT INTO "reagents" VALUES(1261,1186,'2-methylimidazole','C4H6N2','ligand',13.0,'g',NULL,'99%','Acros Organics B.V.B.A. Chemicals Co.','Both n-hexane and HFS, at the aforementioned concentrations, were added to a fixed 20 mL volume of ligand solution (13 g 2-mim in 400 mL DI water) to form mixture-I (Figure 1).','Synthesis Procedures',10085,10261,'2-methylimidazole (2-mim) (C4H6N2; 99%) and zinc nitrate hexahydrate [Zn(NO3)2·6H2O; 98%] were purchased from Acros Organics B.V.B.A. Chemicals Co.');
