INSERT INTO "reagents" VALUES(1263,1186,'zinc nitrate hexahydrate','Zn(NO3)2·6H2O','precursor',5.9,'g',NULL,'98%','Acros Organics B.V.B.A. Chemicals Co.','Subsequently, mixture-I was hard sonicated (2 L Digital Ultrasonic Cleaner Cavitek Professional, 100 W) for 2 h (as shown in Figure 1) before the addition of 20 mL metal solution (5.9 g of zinc nitrate hexahydrate in 400 mL DI water).','Synthesis Procedures',10422,10656,'2-methylimidazole (2-mim) (C4H6N2; 99%) and zinc nitrate hexahydrate [Zn(NO3)2·6H2O; 98%] were purchased from Acros Organics B.V.B.A. Chemicals Co.');
