INSERT INTO "reagents" VALUES(1265,1186,'n-hexane','C6H14','template',4.0,'mL',NULL,'95%','Alfa Aesar','In this part, a fixed concentration of n-hexane (4 mL equivalent to 9 v/v %) was used, while the amount of the HFS surfactant was varied to study their effects on hollow ZIF-8 formation.','Effect of the Amount of HFS Surfactant',38247,38433,'1H,1H,2H,2H-Perfluorodecyltriethoxysilane (HFS) (C16H19F17O3Si; 97%), n-hexane (n-C6H14; 95%), herein referred to as “surfactant” and “oil/solvent” respectively, c-hexane (c-C6H12; 99.8%), and n-dodecane (n-C12H26; 99%) were provided by Alfa Aesar.');
INSERT INTO "reagents" VALUES(1266,1186,'HFS','C16H19F17O3Si','surfactant',0.3,'g',NULL,'97%','Alfa Aesar','only at the S/O ratio of 0.075 g mL–1 (0.3 g of HFS and 4 mL of n-hexane)','Effect of the Amount of HFS Surfactant',38668,38741,'1H,1H,2H,2H-Perfluorodecyltriethoxysilane (HFS) (C16H19F17O3Si; 97%), n-hexane (n-C6H14; 95%), herein referred to as “surfactant” and “oil/solvent” respectively, c-hexane (c-C6H12; 99.8%), and n-dodecane (n-C12H26; 99%) were provided by Alfa Aesar.');
INSERT INTO "reagents" VALUES(1267,1186,'methanol','CH3OH','wash',NULL,NULL,NULL,'>99.8%','Fisher Scientific UK Ltd','After the synthesis, the resultant mixture was centrifuged (Thermo Scientific IEC CL40) at 6000–6500 rpm and repeatedly washed using methanol.','Synthesis Procedures',10906,11048,'Methanol (CH3OH; >99.8%), and ethanol (C2H5OH; >99.8%) was supplied by Fisher Scientific UK Ltd and used as received without further purification.');
INSERT INTO "reagents" VALUES(1268,1194,'ethanol','C2H5OH','template',NULL,NULL,NULL,'>99.8%','Fisher Scientific UK Ltd','The optimized hollow ZIF-8 synthesis conditions were also studied for other co-solvents having different carbon chain lengths (ethanol and n-dodecane) and structural configurations (c-hexane), and the relevant discussion is included with Figure S12.','Order of Reagent Addition and Ligand Concentration',51531,51780,'Methanol (CH3OH; >99.8%), and ethanol (C2H5OH; >99.8%) was supplied by Fisher Scientific UK Ltd and used as received without further purification.');
INSERT INTO "reagents" VALUES(1269,1195,'n-dodecane','C12H26','template',NULL,NULL,NULL,'99%','Alfa Aesar','The optimized hollow ZIF-8 synthesis conditions were also studied for other co-solvents having different carbon chain lengths (ethanol and n-dodecane) and structural configurations (c-hexane), and the relevant discussion is included with Figure S12.','Order of Reagent Addition and Ligand Concentration',51531,51780,'1H,1H,2H,2H-Perfluorodecyltriethoxysilane (HFS) (C16H19F17O3Si; 97%), n-hexane (n-C6H14; 95%), herein referred to as “surfactant” and “oil/solvent” respectively, c-hexane (c-C6H12; 99.8%), and n-dodecane (n-C12H26; 99%) were provided by Alfa Aesar.');
INSERT INTO "reagents" VALUES(1270,1196,'c-hexane','C6H12','template',NULL,NULL,NULL,'99.8%','Alfa Aesar','The optimized hollow ZIF-8 synthesis conditions were also studied for other co-solvents having different carbon chain lengths (ethanol and n-dodecane) and structural configurations (c-hexane), and the relevant discussion is included with Figure S12.','Order of Reagent Addition and Ligand Concentration',51531,51780,'1H,1H,2H,2H-Perfluorodecyltriethoxysilane (HFS) (C16H19F17O3Si; 97%), n-hexane (n-C6H14; 95%), herein referred to as “surfactant” and “oil/solvent” respectively, c-hexane (c-C6H12; 99.8%), and n-dodecane (n-C12H26; 99%) were provided by Alfa Aesar.');
