INSERT INTO "reagents" VALUES(1373,1386,'zinc chloride','ZnCl2','precursor',10.0,'mmol',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','Firstly, 10 mmol ZnCl2 was dispersed in 100 mL methanol and kept stirring vigorously for 30 min until it was dissolved absolutely.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6613,6743,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(1374,1386,'methanol (dispersion of ZnCl2)','CH3OH','solvent',100.0,'mL',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','Firstly, 10 mmol ZnCl2 was dispersed in 100 mL methanol and kept stirring vigorously for 30 min until it was dissolved absolutely.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6613,6743,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(1375,1386,'2-methylimidazole','C4H6N2','ligand',80.0,'mmol',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','Then, 100 mL methanol, containing 80 mmol 2-methylimidazole, was added dropwise into the above solution and intensively stirred for 30 min to form a homogeneous milky suspension.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6744,6922,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(1376,1386,'methanol (solution of 2-methylimidazole)','CH3OH','solvent',100.0,'mL',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','Then, 100 mL methanol, containing 80 mmol 2-methylimidazole, was added dropwise into the above solution and intensively stirred for 30 min to form a homogeneous milky suspension.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6744,6922,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(1377,1386,'silver nitrate','AgNO3','precursor',5.0,'mmol',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','With 5 mmol AgNO3, ZIF-8 also exhibits well-defined truncated rhombic dodecahedral crystals and its particle size decreases to 550 nm (Fig. 2b).','Results and discussion',11521,11665,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(1378,1386,'methanol (solution of AgNO3)','CH3OH','solvent',40.0,'mL',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','Then, 40 mL of methanol, containing 3 mL of H2O and X mmol of AgNO3 (X is 5, 10, 15 and 20, respectively), was injected slowly into the above milky solution and kept stirring for 24 h under dark conditions.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6923,7129,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
