INSERT INTO "reagents" VALUES(1380,1386,'ethanol','C2H5OH','wash',NULL,NULL,NULL,NULL,NULL,'After that, it was centrifuged and washed with ethanol and distilled water to obtain the AgCl(x)@ZIF-8 composites.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7130,7244,NULL);
