INSERT INTO "reagents" VALUES(1382,1386,'distilled water (photoreduction)','H2O','solvent',100.0,'mL',NULL,NULL,NULL,'Finally, 1 g of the AgCl(x)@ZIF-8 composites was dispersed in 100 mL of distilled water and kept stirring vigorously for 30 min under UV light (λ ≤ 400 nm, from a 500 W mercury lamp) to prepare Ag/AgCl(x)@ZIF-8 hybrid photocatalysts.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7245,7478,NULL);
