INSERT INTO "synthesis_routes" VALUES(1171,82,196,NULL,'ZeoX-opt',1,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,1,'["diatomite_amount", "aluminum_hydroxide_amount", "sodium_hydroxide_amount", "water_volume", "stirring_speed", "stirring_duration", "autoclave_volume", "autoclave_fill_fraction", "filtration_method", "reagent_purity", "yield", "scale"]',0.75,'The synthesis of zeolites from diatomite includes three processes as follows: gel formation, aging and crystallization.','2.2. Preparation of Zeolite X',5634,5753,'material');
INSERT INTO "synthesis_routes" VALUES(1172,82,197,1171,'ZeoX-T90',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'the sample at a crystallization temperature of 90 °C showed only one strong diffraction peak at 2θ = 18.35°, which can be attributed to aluminum hydroxide','3.2. Effect of Crystallization',9571,9725,'material');
INSERT INTO "synthesis_routes" VALUES(1173,82,198,1171,'ZeoX-T100',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'When the temperature was raised to 100 °C, typical diffraction peaks of X zeolite (JCPDS 38-0237) can be seen at 2θ = 6.10°, 9.97°, 11.76°, 15.39°, 18.46°, 20.12°, 23.24°, 26.58° and 30.86° suggesting that zeolite X started to crystallize (Figure 2a).','3.2. Effect of Crystallization',9846,10097,'material');
INSERT INTO "synthesis_routes" VALUES(1174,82,199,1171,'ZeoX-T120',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'When the reaction temperature was further raised to 120 °C, almost pure phase of zeolite X was observed along with some zeolite A (JCPDS 43-0142).','3.2. Effect of Crystallization',10381,10527,'material');
INSERT INTO "synthesis_routes" VALUES(1175,82,200,1171,'ZeoX-T130',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,NULL,'[]',0.75,'Increasing temperature of crystallization up to 110 °C increased the CEC but by further increasing the temperature up to 130 °C, the CEC of prepared samples gradually decreased (Figure 5a).','3.2. Effect of Crystallization',12667,12856,'material');
INSERT INTO "synthesis_routes" VALUES(1176,82,201,1171,'ZeoX-t3h',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'As shown in Figure 2b, no zeolite X was obtained at crystallization time of 3 h at 110 °C.','3.2. Effect of Crystallization',10655,10745,'material');
INSERT INTO "synthesis_routes" VALUES(1177,82,202,1171,'ZeoX-t4h',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,NULL,'[]',0.75,'When the crystallization time was 4 h, the synthesized products formed crystals with no distinct faces, and the particles were not uniform.','3.2. Effect of Crystallization',11968,12107,'material');
INSERT INTO "synthesis_routes" VALUES(1178,82,203,1171,'ZeoX-t6h',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,NULL,'[]',0.75,'When the crystallization time was up to 6 h, the synthesized products do not show smooth faces.','3.2. Effect of Crystallization',12219,12314,'material');
INSERT INTO "synthesis_routes" VALUES(1179,82,204,1171,'ZeoX-age0',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'However, the synthetic product without aging exhibited extremely weak diffraction peaks of zeolite X (Figure 6b).','3.3. Effect of Aging',14156,14269,'material');
INSERT INTO "synthesis_routes" VALUES(1180,82,205,1171,'ZeoX-age60',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'However, when the aging time was up to 60 and 120 min, some obvious diffraction peaks of zeolite A appeared indicating that the aging time plays a significant role in the formation of zeolite prepared from diatomite.','3.3. Effect of Aging',14545,14761,'material');
INSERT INTO "synthesis_routes" VALUES(1181,82,206,1171,'ZeoX-age120',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'However, when the aging time was up to 60 and 120 min, some obvious diffraction peaks of zeolite A appeared indicating that the aging time plays a significant role in the formation of zeolite prepared from diatomite.','3.3. Effect of Aging',14545,14761,'material');
