INSERT INTO "synthesis_routes" VALUES(1185,82,210,1171,'ZeoX-NS1.5',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,1,'[]',0.75,'Figure 9 shows that all samples with Na2O/SiO2 ratios of 1.3, 1.4 and 1.5 exhibited high crystallinity with smooth faces.','3.4. Effect of Alkalinity',17111,17232,'material');
INSERT INTO "synthesis_routes" VALUES(1186,18,211,NULL,'ZIF-8-Ins',1,'soft-templating synthesis in a surfactant-stabilized oil-in-water microemulsion (n-hexane/HFS), ultrasonication then low-temperature synthesis at 30 °C',NULL,NULL,NULL,NULL,1,'["yield", "centrifugation_duration", "number_of_washes", "methanol_volume", "drying_duration_numeric", "reaction_vessel", "volume_of_stock_solution_used_in_ratio"]',0.75,'Herein, we report a facile, one-pot, highly controlled soft-templating synthesis strategy for hollow ZIF-8 nanospheres with reduced synthesis time, energy consumption and overall chemical usage, ensuring the environmental friendliness of the synthesis procedure.','Introduction',7163,7425,'material');
INSERT INTO "synthesis_routes" VALUES(1187,18,212,1186,'ZIF-8-Out',0,'soft-templating synthesis in a surfactant-stabilized oil-in-water microemulsion (n-hexane/HFS), ultrasonication then low-temperature synthesis at 30 °C',NULL,NULL,NULL,NULL,1,'[]',0.75,'Depending on whether the step was performed without or with sonication, the corresponding samples were named as ZIF-8-Out (Figure 3d) and ZIF-8-Ins (Figure 3e), respectively.','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',27673,27847,'material');
