INSERT INTO "synthesis_routes" VALUES(1237,56,254,NULL,'QD_EtOAc',1,'room temperature, open atmosphere anti-solvent precipitation in ethyl acetate with oleylamine and oleic acid as capping ligands',NULL,NULL,NULL,NULL,1,'["OLA_amount", "OA_amount", "stirring_speed", "reaction_temperature_value", "wash_volume", "number_of_washes", "yield"]',0.875,'When ethyl acetate is used as the anti-solvent, 2.6 ± 0.9 nm sized quasi-cubic CsPbBr3 QDs are formed immediately on addition of the precursor solution.','Quantum Dots',4630,4782,'material');
