INSERT INTO "synthesis_routes" VALUES(1241,56,258,1240,'NC34_toluene_1h',0,NULL,NULL,NULL,NULL,NULL,1,'[]',0.875,'When 70 μl OLA is used, larger nanocubes of ~34 nm edge-length are formed as evident from the TEM (Fig. 2d, S6, SI) and FESEM (Fig. 2e) images.','Nanocubes of Different Sizes',9086,9229,'material');
INSERT INTO "synthesis_routes" VALUES(1242,56,259,1241,'NC_toluene_50h',0,NULL,NULL,NULL,NULL,NULL,NULL,'[]',0.875,'Further increase in reaction time up to 50 hours or more ends up with larger nanocubes and few nanorods of larger dimension (Figure S7, SI).','Nanocubes of Different Sizes',9568,9708,'material');
INSERT INTO "synthesis_routes" VALUES(1243,56,260,1240,'NR_toluene_1h',0,NULL,NULL,NULL,NULL,NULL,1,'[]',0.875,'Less quantity of OLA (20 μl) provides a faster kinetics and forms CsPbBr3 nanorods of good crystalline quality (after 1 hour) at the expense of nanocubes formed initially.','Nanorods and Nanowires',9735,9906,'material');
INSERT INTO "synthesis_routes" VALUES(1244,56,261,1243,'NW_toluene_40h',0,NULL,NULL,NULL,NULL,NULL,1,'[]',0.875,'after 40 hours of reaction, nanowires of diameter ~70 nm and length ≥15 μm are obtained.','Nanorods and Nanowires',10665,10753,'material');
